1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = { itemType: string; amount: number };
14	
15	export type ClaimStep = {
16	  op: "claim";
17	  policy: number;
18	  incident: { cause: string; damages: Damage[] };
19	};
20	
21	export type Step = QuoteStep | ClaimStep;
22	
23	export type Customer = { yearsWithMHPCO: number };
24	
25	export type Scenario = {
26	  customer: Customer;
27	  steps: Step[];
28	};
29	
30	export type ScenarioResults = {
31	  results: unknown[];
32	};
33	
34	const PROCESSING_FEE = 5;
35	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
36	const LOYALTY_DISCOUNT = 0.2;
37	const LOYALTY_YEARS = 2;
38	const FOLLOW_UP_DISCOUNT = 0.15;
39	
40	const BASE_PREMIUMS: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	
49	const INSURANCE_VALUES: Record<string, number> = {
50	  sword: 1000,
51	  amulet: 600,
52	  staff: 800,
53	  potion: 400,
54	  rune: 250,
55	  moonstone: 250,
56	};
57	
58	const DEDUCTIBLE = 100;
59	const CAP_MULTIPLE = 2;
60	const HALF_REIMBURSEMENT_LEVEL = 8;
61	const HALF_REIMBURSEMENT = 0.5;
62	const FULL_REIMBURSEMENT = 1;
63	const DRAGON_MATERIAL = "dragon";
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_BASE_PREMIUM = 60;
67	
68	const COMPONENT_TYPES = ["rune", "moonstone"];
69	
70	/** Items are priced per type, because the component block applies to alike items. */
71	const groupByType = (items: Item[]): Map<string, Item[]> =>
72	  items.reduce(
73	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
74	    new Map<string, Item[]>(),
75	  );
76	
77	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
78	
79	/**
80	 * Item-level risk surcharges, each a rate on the item's own base premium.
81	 * They are separate addends: unlike the policy-level initial assessment, they
82	 * do not compound with each other or with it.
83	 */
84	const CURSE_SURCHARGE = 0.5;
85	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
86	const HIGH_ENCHANTMENT_LEVEL = 5;
87	
88	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
89	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
90	  {
91	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
92	    rate: HIGH_ENCHANTMENT_SURCHARGE,
93	  },
94	];
95	
96	const itemSurchargeTotal = (item: Item): number =>
97	  ITEM_SURCHARGE_RULES.filter(({ applies }) => applies(item)).reduce(
98	    (sum, { rate }) => sum + itemBasePremium(item) * rate,
99	    0,
100	  );
101	
102	/**
103	 * A building block of exactly 3 alike components is offered at a special base
104	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
105	 * runes are charged per item.
106	 */
107	const formsComponentBlock = (type: string, items: Item[]): boolean =>
108	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
109	
110	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
111	  formsComponentBlock(type, items)
112	    ? BLOCK_BASE_PREMIUM
113	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
114	
115	const policyBasePremium = (items: Item[]): number =>
116	  [...groupByType(items)].reduce(
117	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
118	    0,
119	  );
120	
121	/**
122	 * Money is always rounded in the MHPCO's favour. Which way that is depends on
123	 * the direction it flows: a premium is paid *to* the MHPCO, so it rounds up;
124	 * a payout is paid *by* it, so it rounds down (see `roundPayoutInMHPCOsFavour`).
125	 */
126	const roundPremiumInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
127	
128	/**
129	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
130	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
131	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
132	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
133	 */
134	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
135	
136	const policyItemSurchargeTotal = (items: Item[]): number =>
137	  items.reduce((sum, item) => sum + itemSurchargeTotal(item), 0);
138	
139	/**
140	 * Policy-level modifiers, each a signed rate on the policy base premium.
141	 * Like the item-level surcharges they are independent addends: they do not
142	 * compound with one another. A discount is simply a negative rate.
143	 */
144	type Policy = { items: Item[]; paidOut: number };
145	
146	type ScenarioState = {
147	  customer: Customer;
148	  contractsIssued: number;
149	  policies: Map<number, Policy>;
150	};
151	
152	const POLICY_MODIFIER_RULES: { applies: (state: ScenarioState) => boolean; rate: number }[] = [
153	  {
154	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
155	    rate: -LOYALTY_DISCOUNT,
156	  },
157	  { applies: ({ contractsIssued }) => contractsIssued > 0, rate: -FOLLOW_UP_DISCOUNT },
158	];
159	
160	const policyModifierTotal = (basePremium: number, state: ScenarioState): number =>
161	  POLICY_MODIFIER_RULES.filter(({ applies }) => applies(state)).reduce(
162	    (sum, { rate }) => sum + basePremium * rate,
163	    0,
164	  );
165	
166	/**
167	 * The premium is the policy base premium plus a set of independent addends,
168	 * each a rate on that same base — they do not compound with one another:
169	 *
170	 *   100 base + 50 curse + 30 high ench - 20 loyalty + 10 first insurance = 170, + 5 fee
171	 *
172	 * The initial assessment surcharge is expressed via `withSurcharge` (base plus
173	 * its own rate) rather than as a bare addend, to keep the IEEE-754 behaviour
174	 * documented there.
175	 */
176	const quote = (step: QuoteStep, state: ScenarioState): { premium: number } => {
177	  const basePremium = policyBasePremium(step.items);
178	  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
179	  const itemSurcharges = policyItemSurchargeTotal(step.items);
180	  const policyModifiers = policyModifierTotal(basePremium, state);
181	
182	  return {
183	    premium: roundPremiumInMHPCOsFavour(
184	      assessedPremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
185	    ),
186	  };
187	};
188	
189	/** The payout half of the rule on `roundPremiumInMHPCOsFavour`: down. */
190	const roundPayoutInMHPCOsFavour = (payout: number): number => Math.floor(payout);
191	
192	const insuranceSum = (items: Item[]): number =>
193	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
194	
195	/**
196	 * Reimbursement clauses, in precedence order: the first one that applies wins.
197	 * Unlike the premium's surcharges these are alternatives, not addends — a
198	 * dragon-material item enchanted to 9 is reimbursed at 50 %, not at 150 %.
199	 *
200	 * The dragon-material clause is written out even though it currently yields the
201	 * same rate as the default. It is a distinct rule of the domain — the spec calls
202	 * it "the only clause that applies" for an unenchanted dragon item, rather than
203	 * calling it no clause at all — and it merely *coincides* with the default
204	 * today. Naming it is what makes the precedence above visible: without it there
205	 * is nothing for the half-reimbursement clause to win against.
206	 */
207	const REIMBURSEMENT_CLAUSES: { applies: (item: Item) => boolean; rate: number }[] = [
208	  {
209	    applies: (item) => (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL,
210	    rate: HALF_REIMBURSEMENT,
211	  },
212	  { applies: (item) => item.material === DRAGON_MATERIAL, rate: FULL_REIMBURSEMENT },
213	];
214	
215	const reimbursementRate = (item: Item): number =>
216	  REIMBURSEMENT_CLAUSES.find(({ applies }) => applies(item))?.rate ?? FULL_REIMBURSEMENT;
217	
218	/**
219	 * The clause applies to the damage amount; the deductible is subtracted
220	 * afterwards, per damage event — i.e. once per damaged item.
221	 */
222	const reimbursedAmount = (item: Item, amount: number): number =>
223	  amount * reimbursementRate(item);
224	
225	const damagePayout = (damage: Damage, policy: Policy): number => {
226	  const item = policy.items.find(({ type }) => type === damage.itemType) as Item;
227	
228	  return reimbursedAmount(item, damage.amount) - DEDUCTIBLE;
229	};
230	
231	/**
232	 * A claim names the policy it is made against by the step index of the quote
233	 * that created it. That the policy exists is currently an *assumption*, not a
234	 * guarantee — a claim naming an unissued policy is a specified error case that
235	 * is not implemented yet, so this deliberately still fails on `undefined`.
236	 * The assumption is named here so that the missing check is visible rather
237	 * than buried in an `as` cast.
238	 */
239	const assumeIssued = (policy: Policy | undefined): Policy => policy as Policy;
240	
241	/**
242	 * The total payout per policy is capped at twice its insurance sum, across all
243	 * claims. A claim that would exceed what is left is reduced to the remainder.
244	 */
245	const claim = (
246	  step: ClaimStep,
247	  state: ScenarioState,
248	): { result: { payout: number; remainingCap: number }; policy: Policy } => {
249	  const policy = assumeIssued(state.policies.get(step.policy));
250	  const cap = CAP_MULTIPLE * insuranceSum(policy.items);
251	  const desiredPayout = roundPayoutInMHPCOsFavour(
252	    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage, policy), 0),
253	  );
254	  const payout = Math.min(desiredPayout, cap - policy.paidOut);
255	  const paidOut = policy.paidOut + payout;
256	
257	  return { result: { payout, remainingCap: cap - paidOut }, policy: { ...policy, paidOut } };
258	};
259	
260	/**
261	 * Steps are processed in order and later steps depend on earlier ones — a quote
262	 * issues a contract that discounts every following quote, and a claim is made
263	 * against a policy an earlier quote created. Each step therefore maps its
264	 * incoming state to a result plus the state the next step sees.
265	 */
266	const runStep = (
267	  step: Step,
268	  state: ScenarioState,
269	  index: number,
270	): { result: unknown; nextState: ScenarioState } => {
271	  if (step.op === "quote") {
272	    return {
273	      result: quote(step, state),
274	      nextState: {
275	        ...state,
276	        contractsIssued: state.contractsIssued + 1,
277	        policies: new Map(state.policies).set(index, { items: step.items, paidOut: 0 }),
278	      },
279	    };
280	  }
281	
282	  const { result, policy } = claim(step, state);
283	
284	  return {
285	    result,
286	    nextState: { ...state, policies: new Map(state.policies).set(step.policy, policy) },
287	  };
288	};
289	
290	export const runScenario = (scenario: Scenario): ScenarioResults => {
291	  const { results } = scenario.steps.reduce<{
292	    results: unknown[];
293	    state: ScenarioState;
294	  }>(
295	    ({ results, state }, step, index) => {
296	      const { result, nextState } = runStep(step, state, index);
297	
298	      return { results: [...results, result], state: nextState };
299	    },
300	    {
301	      results: [],
302	      state: { customer: scenario.customer, contractsIssued: 0, policies: new Map() },
303	    },
304	  );
305	
306	  return { results };
307	};
