/**
 * The total payout per policy is capped at twice its insurance sum, across all
 * claims. A claim that would exceed what is left is reduced to the remainder.
 */
const claim = (
  step: ClaimStep,
  state: ScenarioState,
): { result: { payout: number; remainingCap: number }; policy: Policy } => {
  const policy = assumeIssued(state.policies.get(step.policy));
  const cap = CAP_MULTIPLE * insuranceSum(policy.items);
  const desiredPayout = roundPayoutInMHPCOsFavour(
    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage, policy), 0),
  );
  const payout = Math.min(desiredPayout, cap - policy.paidOut);
  const paidOut = policy.paidOut + payout;

  return { result: { payout, remainingCap: cap - paidOut }, policy: { ...policy, paidOut } };
};

/**
 * Steps are processed in order and later steps depend on earlier ones — a quote
 * issues a contract that discounts every following quote, and a claim is made
 * against a policy an earlier quote created. Each step therefore maps its
 * incoming state to a result plus the state the next step sees.
 */
const runStep = (
  step: Step,
  state: ScenarioState,
  index: number,
): { result: unknown; nextState: ScenarioState } => {
  if (step.op === "quote") {
    return {
      result: quote(step, state),
      nextState: {
        ...state,
        contractsIssued: state.contractsIssued + 1,
        policies: new Map(state.policies).set(index, { items: step.items, paidOut: 0 }),
      },
    };
  }

  const { result, policy } = claim(step, state);

  return {
    result,
    nextState: { ...state, policies: new Map(state.policies).set(step.policy, policy) },
  };
};

